function icon(name, size=22){return `<svg aria-hidden="true" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${paths[name]||paths.spark}</svg>`}
function esc(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
const state={page:'landing',nav:'الرئيسية',mode:'signup',profile:null,guest:false,testAnswers:{},message:'',progress:LiplipProgress.hydrate(null),chatMode:null,comingContext:null,confirmReset:false,lessonTab:'discover',lessonReviewed:[],lessonWritten:[],lessonSpoken:[],lessonAttempts:{},lessonRating:null,lessonFeedback:'',editorOpen:false,editorBox:null,editorDraft:null,editorMessage:'',confirmDelete:false,justCompleted:null,closetView:null,closetIndex:0,studyMapView:'levels',studyMapLevel:null,studyMapStep:null,studyReviewBox:null};
try {const saved=JSON.parse(sessionStorage.getItem('liplip-preview')||'null');if(saved&&typeof saved==='object'){if(saved.profile&&typeof saved.profile.name==='string')state.profile=saved.profile;state.guest=saved.guest===true;state.progress=LiplipProgress.hydrate(saved.progress);if(state.profile||state.guest)state.page='app'}}catch{}
try{const savedProgress=JSON.parse(localStorage.getItem('liplip-progress-v1')||'null');if(savedProgress)state.progress=LiplipProgress.hydrate(savedProgress)}catch{}
function save(){try{sessionStorage.setItem('liplip-preview',JSON.stringify({profile:state.profile,guest:state.guest,progress:state.progress}))}catch{}try{localStorage.setItem('liplip-progress-v1',JSON.stringify(state.progress))}catch{}}
function logo(){return `<a href="#" class="logo" data-action="landing" aria-label="لُبلُب، الصفحة الأولى"><span class="logo-word" lang="ar" dir="rtl">لُبلُب</span></a>`}
function header(){return `<header class="topbar">${logo()}<div class="top-actions"><span class="header-note">من العراق، إلى العالم</span>${state.page==='landing'?`<button class="header-button" data-action="auth">تسجيل الدخول ${icon('arrow',18)}</button>`:''}</div></header>`}
function landing(){return `<main class="landing"><section class="hero wrap"><div class="hero-copy"><span class="eyebrow">${icon('spark',16)} مساحة جديدة لتعلّم اللغات</span><h1>كل كلمة،<br><em>تفتح لك عالماً.</em></h1><p>تعلّم بطريقتك، واكتشف فرصاً أبعد مما تتخيّل. رحلتك مع اللغات تبدأ من هنا، أينما كنت في العراق.</p><div class="hero-actions"><button class="cta" data-action="auth">انضم إلى liplip ${icon('arrow',21)}</button><span class="aside-note">خطوتك الأولى بسيطة وممتعة</span></div><div class="hero-foot"><span class="tiny-mark">${icon('check',15)}</span> فضولك كافٍ لتبدأ</div></div><div class="hero-art" role="img" aria-label="رسم تجريدي لفقاعة حوار وكلمات بلغات مختلفة"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="art-blob"></div><div class="art-main"><div class="art-icon">${icon('chat',100)}</div><div class="art-line"></div><div class="art-line short"></div><strong>مرحباً بالعالم</strong></div><div class="word-card word-one"><span class="word-dot pink"></span> Hello!</div><div class="word-card word-two"><span class="word-dot mint"></span> أهلاً وسهلاً</div><div class="word-card word-three"><span class="word-dot gold"></span> Bonjour!</div><span class="art-spark spark-one">${icon('spark',43)}</span><span class="art-spark spark-two">${icon('spark',27)}</span></div></section><div class="marquee"><div class="wrap marquee-inner"><span>${icon('globe',23)} من العراق، إلى كل مكان</span><i></i><span>${icon('heart',23)} تعلّم على راحتك</span><i></i><span>${icon('spark',23)} بداية صغيرة، عالم كبير</span></div></div><section class="features wrap"><span class="section-kicker">رحلة على مقاسك</span><h2>البداية الحلوة من هنا.</h2><p class="section-lead">مكان يشجّعك على المحاولة، ويفتح لك باباً جديداً كل يوم.</p><div class="feature-grid"><article class="feature feature-lilac"><div class="feature-icon">${icon('compass',31)}</div><span class="feature-number">01</span><h3>امشِ بخطاك</h3><p>ابدأ من مستواك الحقيقي، وتقدّم بإيقاع يناسب يومك وحياتك.</p></article><article class="feature feature-peach"><div class="feature-icon">${icon('chat',31)}</div><span class="feature-number">02</span><h3>احكِ بثقة</h3><p>كل كلمة تتعلّمها تقرّبك من محادثة جديدة وفرصة أجمل.</p></article><article class="feature feature-mint"><div class="feature-icon">${icon('globe',31)}</div><span class="feature-number">03</span><h3>وسّع عالمك</h3><p>اللغات تفتح لك أبواب المعرفة، والناس، والأماكن البعيدة.</p></article></div></section><section class="end-banner wrap"><div><span class="section-kicker">جاهز للخطوة الأولى؟</span><h2>العالم ينتظر صوتك.</h2></div><button class="cta cta-light" data-action="auth">ابدأ رحلتك ${icon('arrow',20)}</button></section></main><footer class="footer"><div class="wrap"><span>© ${new Date().getFullYear()} liplip</span><span>صُنع بحبّ للفضوليين في العراق</span></div></footer>`}
function auth(){const signup=state.mode==='signup';return `<main class="auth-layout"><div class="auth-art"><div class="auth-art-content"><div class="auth-art-icon">${icon('globe',110)}</div><span class="section-kicker">liplip، مساحتك الجديدة</span><h2>خطوة صغيرة.<br>عالم من الاحتمالات.</h2><p>لكل حكاية كلمة أولى. خلّينا نبدأ حكايتك.</p><div class="auth-bubble bubble-a">أهلاً بك</div><div class="auth-bubble bubble-b">Let’s go</div></div></div><div class="auth-panel"><div class="form-card"><button class="back" data-action="landing">${icon('back',17)} العودة إلى البداية</button><span class="section-kicker">أهلاً بك في liplip</span><h1>${signup?'خلّينا نتعرّف.':'نورت من جديد.'}</h1><p class="muted">${signup?'أنشئ مساحتك وابدأ رحلتك بخطوات بسيطة.':'تابع رحلتك أو ادخل سريعاً كضيف.'}</p><div class="tabs" role="tablist" aria-label="نوع الدخول"><button role="tab" aria-selected="${signup}" class="${signup?'active':''}" data-action="signup">إنشاء حساب</button><button role="tab" aria-selected="${!signup}" class="${!signup?'active':''}" data-action="signin">تسجيل الدخول</button></div><form id="auth-form"><div class="field"><label for="email">البريد الإلكتروني</label><input id="email" name="email" type="email" dir="ltr" placeholder="you@example.com" required autocomplete="email"></div><button class="cta full" type="submit">متابعة إلى التجربة ${icon('arrow',19)}</button></form>${!signup?`<button class="guest-button" data-action="guest">${icon('bolt',21)} دخول سريع كضيف <span>بدون تسجيل</span></button>`:''}<div class="divider"><span>أو باستخدام</span></div><div class="social"><button type="button" data-provider="Google">${icon('google',21)} Google</button><button type="button" data-provider="Facebook">${icon('facebook',21)} Facebook</button><button type="button" data-provider="WhatsApp">${icon('phone',21)} WhatsApp</button></div><p id="auth-message" class="notice ${state.message?'error':''}" role="status">${state.message?esc(state.message):'هذه نسخة تجريبية. لا يتم إنشاء حساب حقيقي، وخيارات الربط الخارجي قيد الإعداد.'}</p></div></div></main>`}
function ageFromBirth(value){if(!/^\d{4}-\d{2}-\d{2}$/.test(value||''))return null;const d=new Date(value+'T12:00:00');if(Number.isNaN(d.getTime())||d.toISOString().slice(0,10)!==value)return null;const now=new Date();let age=now.getFullYear()-d.getFullYear();if(now.getMonth()<d.getMonth()||(now.getMonth()===d.getMonth()&&now.getDate()<d.getDate()))age--;return age}
function profile(){const p=state.profile||{};const age=p.birth?ageFromBirth(p.birth):null;return `<main class="profile-shell"><div class="step-line"><span>خطوتك الأولى</span><span>01 / 02</span></div><div class="progress"><span style="width:50%"></span></div><span class="section-kicker">خلّينا نبدأ صح</span><h1>نحب نتعرّف عليك.</h1><p class="lead">بعض التفاصيل تساعدنا نجهّز مساحتك. في هذه النسخة التجريبية تبقى بياناتك داخل تبويب المتصفح فقط.</p><form id="profile-form"><div class="form-grid"><div class="field span-2"><label for="fullName">الاسم الكامل</label><input id="fullName" name="name" type="text" minlength="2" maxlength="80" autocomplete="name" required placeholder="بماذا تحب أن نناديك؟" value="${esc(p.name||'')}"></div><div class="field"><label for="birth">تاريخ الميلاد</label><input id="birth" name="birth" type="date" required max="${new Date().toISOString().slice(0,10)}" value="${esc(p.birth||'')}"><small id="age-display">${age===null?'سنحسب عمرك تلقائياً.':`العمر: ${age} سنة`}</small></div><div class="field"><label for="gender">الجنس</label><select id="gender" name="gender" required><option value="">اختر ما يناسبك</option>${['أنثى','ذكر','آخر','أفضل عدم الإفصاح'].map(v=>`<option ${p.gender===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="city">المحافظة في العراق</label><select id="city" name="city" required><option value="">اختر المحافظة</option>${cities.map(v=>`<option ${p.city===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="town">المدينة أو المنطقة</label><input id="town" name="town" type="text" maxlength="80" required placeholder="مثلاً: المنصور" value="${esc(p.town||'')}"></div><div class="field span-2"><label for="level">مستواك في اللغة الإنجليزية</label><select id="level" name="level" required><option value="">اختر مستواك</option><option value="a1" ${p.level==='a1'?'selected':''}>مبتدئ A1</option><option value="a2" ${p.level==='a2'?'selected':''}>أساسي A2</option><option value="b1" ${p.level==='b1'?'selected':''}>متوسط B1</option><option value="b2" ${p.level==='b2'?'selected':''}>فوق المتوسط B2</option><option value="c1" ${p.level==='c1'?'selected':''}>متقدم C1 أو أعلى</option><option value="unknown">لا أعرف — أريد اختباراً سريعاً</option></select><small>الاختبار السريع للتوجيه الأولي، وليس شهادة مستوى معتمدة.</small></div></div><p id="profile-error" class="notice error" role="alert"></p><button class="cta" type="submit">متابعة ${icon('arrow',19)}</button></form></main>`}
const questions=[
 {q:'Choose the correct greeting:',a:['Good morning!','Good mornings!','Morning good!'],right:0},
 {q:'She ___ to school every day.',a:['go','goes','going'],right:1},
 {q:'If it rains tomorrow, we ___ at home.',a:['stay','stayed','will stay'],right:2},
 {q:'Choose the closest meaning of “reliable”:',a:['Dependable','Interesting','Expensive'],right:0},
 {q:'By the time I arrived, they ___ dinner.',a:['finished','had finished','finish'],right:1}
];
function test(){return `<main class="profile-shell"><div class="step-line"><span>اختبار تحديد البداية</span><span>02 / 02</span></div><div class="progress"><span style="width:100%"></span></div><span class="section-kicker">بدون ضغط</span><h1>وين تحب تبدأ؟</h1><p class="lead">خمسة أسئلة بسيطة بالإنجليزية تعطينا فكرة تقريبية عن نقطة البداية. النتيجة ليست تقييماً معتمداً.</p><form id="test-form">${questions.map((q,i)=>`<fieldset class="question"><legend>${i+1}. <span dir="ltr">${esc(q.q)}</span></legend><div class="answers" dir="ltr">${q.a.map((a,j)=>`<label><input type="radio" name="q${i}" value="${j}" required ${state.testAnswers[i]===j?'checked':''}>${esc(a)}</label>`).join('')}</div></fieldset>`).join('')}<button class="cta" type="submit">شوف نقطة بدايتك ${icon('arrow',19)}</button></form></main>`}
function nav(){return `<nav class="mainnav" aria-label="التنقّل الرئيسي">${sections.map(s=>`<button class="navitem ${state.nav===s.name?'active':''}" data-nav="${s.name}" aria-label="${s.name}" title="${s.name}" ${state.nav===s.name?'aria-current="page"':''}>${icon(s.icon,24)}</button>`).join('')}</nav>`}
function levelLabel(value){const map={a1:'مبتدئ A1',a2:'أساسي A2',b1:'متوسط B1',b2:'فوق المتوسط B2',c1:'متقدم C1+',starter:'بداية مقترحة: مبتدئ',elementary:'بداية مقترحة: أساسي',intermediate:'بداية مقترحة: متوسط'};return map[value]||value||'مستكشف'}
function meter(label,iconName,value,caption){return `<div class="skill-meter"><span class="skill-icon">${icon(iconName,20)}</span><div><strong>${label}</strong><small>${caption}</small></div><b>${value===null?'—':`${value}%`}</b></div>`}
function levelTrack(s){return `<div class="level-track" aria-label="المستويات من A0 إلى C2">${LiplipProgress.LEVELS.map((v,i)=>`<span class="${i===s.levelIndex?'current':i<s.levelIndex?'passed':''}">${v}</span>`).join('')}</div>`}
function waypoint(s,tone=''){return `<section class="waypoint status-strip ${tone}" aria-label="موقعك في رحلة التعلّم"><div class="status-upper"><div class="status-level-copy"><span class="status-label">مستواك الحالي</span><span class="status-caption">مؤشر التعلّم · A0–C2</span></div><strong class="status-level" dir="ltr">${s.level}</strong></div><div class="status-lower"><div><span>المرحلة ${s.position.stage}</span><strong title="${esc(s.stageName)}">${esc(s.stageName)}</strong></div><div><span>الخطوة ${s.position.step}</span><strong title="${esc(s.stepName)}">${esc(s.stepName)}</strong></div><div><span>${s.currentBox===null?'اكتمل المسار':`الصندوق ${s.position.box}`}</span><strong title="${esc(s.boxName)}">${esc(s.boxName)}</strong></div></div></section>`}
function systemPanel(s){const stage=s.position.stage,step=s.position.step;return `<section class="system-panel"><div class="panel-heading"><div><span class="section-kicker">كيف تعمل رحلتك؟</span><h2>مسار واحد، أربع طرق للتعلّم.</h2><p>٥ مراحل، في كل مرحلة ١٠ خطوات، وفي كل خطوة ٢٠ صندوقاً: ١٠٠٠ صندوق بالمجموع. صندوقك الحالي مشترك بين الدراسة والمشاهدة والقراءة والمحادثة.</p></div><span class="panel-count">${s.completedCount} / ${s.totalBoxes} صندوق</span></div><div class="system-paths"><div>${icon('book',24)}<strong>ادرس</strong><small>كلمات · نطق · كتابة</small></div><div>${icon('play',24)}<strong>شاهد</strong><small>استماع وفهم</small></div><div>${icon('file',24)}<strong>اقرأ</strong><small>قراءة وفهم</small></div><div>${icon('chat',24)}<strong>تحدّث</strong><small>تواصل · لكنة · طلاقة</small></div></div><div class="stage-row">${s.stages.map((name,i)=>{const done=Math.max(0,Math.min(200,s.completedCount-i*200));return `<div class="stage-tile ${i===stage-1?'selected':''}"><span>المرحلة ${i+1}</span><strong>${name}</strong><small>${done} / ٢٠٠ صندوق</small></div>`}).join('')}</div><div class="step-heading"><div><h3>${esc(s.stageName)} · ${esc(s.stepName)}</h3><p>الخطوة ${step} من ١٠ · الصندوق ${s.position.box} من ٢٠</p></div><span>${s.currentBox===null?'اكتمل المسار':esc(s.boxName)}</span></div><div class="step-track">${Array.from({length:10},(_,i)=>`<span class="${i+1===step?'active':''}">${i+1}</span>`).join('')}</div><div class="box-grid" aria-label="صناديق الخطوة الحالية">${Array.from({length:20},(_,i)=>{const id=(stage-1)*200+(step-1)*20+i+1;const done=state.progress.completedBoxes.includes(id),active=id===s.currentBox;return `<div class="box ${done?'done':active?'active':'locked'}" title="${done?'مكتمل':active?'الصندوق الحالي':'لم يفتح بعد'}">${done?icon('check',16):active?icon('book',16):icon('lock',14)}<span>${i+1}</span></div>`}).join('')}</div><p class="system-disclaimer">المستوى A0–C2 مؤشر داخلي تجريبي؛ لا يتغير إلا بعد أنشطة مكتملة وتقييمات فعلية للمهارات السبع. ليس شهادة CEFR.</p></section>`}
function dashboard(){const first=state.guest?'ضيفنا':(state.profile?.name||'صديقنا').trim().split(/\s+/)[0];const s=LiplipProgress.snapshot(state.progress);return `<main class="dashboard"><div class="dash-intro"><div><span class="section-kicker">مساحتك الخاصة</span><h1>هلا ${esc(first)}، نورت!</h1><p>تقدّمك في كل طرق التعلّم يظهر هنا في مكان واحد.</p></div><span class="badge">${icon(state.guest?'user':'spark',17)} ${state.guest?'تصفّح كضيف':'رحلة التعلّم'}</span></div><div class="level-hero"><div class="level-copy"><span class="section-kicker">مستواك الحالي في liplip</span><div class="level-value">${s.level}<small>مؤشر تقدّم تجريبي</small></div><p>يعتمد على الكلمات والصناديق المكتملة وتقييمات الدراسة والاستماع والقراءة والمحادثة. لا يُعدّ شهادة CEFR.</p>${levelTrack(s)}</div><div class="level-symbol" aria-hidden="true">${icon('target',108)}</div></div><div class="overview-stats"><article><span>${icon('closet',23)}</span><div><b>${s.vocabularyCount}</b><small>كلمة في الخزانة</small></div></article><article><span>${icon('layers',23)}</span><div><b>${s.completedCount} / ${s.totalBoxes}</b><small>صندوق مكتمل</small></div></article><article><span>${icon('compass',23)}</span><div><b>${esc(s.stageName)}</b><small>المرحلة الحالية</small></div></article></div>${systemPanel(s)}<div class="dashboard-grid"><article><div class="tile-icon lilac">${icon('book',27)}</div><h3>ابدأ من الصندوق الحالي</h3><p>تعلّم كلمات جديدة وجرّب النطق والكتابة في مسار الدراسة.</p><button class="text-link" data-nav="الدراسة">اذهب إلى الدراسة ${icon('arrow',17)}</button></article><article><div class="tile-icon peach">${icon('media',27)}</div><h3>شاهد واقرأ</h3><p>استخدم ما تعلّمته لفهم مقطع أو نص ضمن خطوتك الحالية.</p><button class="text-link" data-nav="شاهد واقرأ">استكشف المسار ${icon('arrow',17)}</button></article><article><div class="tile-icon lilac">${icon('chat',27)}</div><h3>خلّي الكلام أسهل</h3><p>تدرّب على التواصل واللكنة والطلاقة في مساحة المحادثة.</p><button class="text-link" data-nav="تحدّث">اذهب إلى التحدّث ${icon('arrow',17)}</button></article></div></main>`}

const STUDY_PROCESS_NAMES=['المفردات','اختبار المفردات','الاستماع والتحدث','اختبار الاستماع','القواعد'];
const STUDY_PHASE_LABELS=['المفردات','اختبار المفردات','الاستماع والتحدث','اختبار الاستماع','القواعد','الامتحان النهائي'];
function studyMapModel(){
 const snap=LiplipProgress.snapshot(state.progress),completed=new Set(state.progress.completedBoxes||[]),current=snap.currentBox,currentPos=current?LiplipProgress.location(current):{stage:5,step:10,box:20},allComplete=current===null,zone=current?LiplipZone.progressInfo(current):{phase:5,hasSaved:false};
 const boxProcesses=id=>completed.has(id)?5:id===current?Math.max(0,Math.min(5,zone.phase)):0;
 const boxPercent=id=>completed.has(id)?100:id===current?Math.round(boxProcesses(id)/5*90):0;
 const stepStat=(level,step)=>{const ids=Array.from({length:20},(_,i)=>(level-1)*200+(step-1)*20+i+1),done=ids.filter(id=>completed.has(id)).length,percent=Math.round(ids.reduce((sum,id)=>sum+boxPercent(id),0)/20);return {done,percent}};
 const levelStat=level=>{const steps=Array.from({length:10},(_,i)=>stepStat(level,i+1)),done=steps.filter(x=>x.done===20).length,percent=Math.round(steps.reduce((sum,x)=>sum+x.percent,0)/10);return {done,percent}};
 const statusLevel=level=>allComplete||level<currentPos.stage?'done':level===currentPos.stage?'current':'locked';
 const statusStep=(level,step)=>allComplete||level<currentPos.stage||level===currentPos.stage&&step<currentPos.step?'done':level===currentPos.stage&&step===currentPos.step?'current':'locked';
 const statusBox=id=>completed.has(id)?'done':id===current?'current':'locked';
 return {snap,completed,current,currentPos,allComplete,zone,boxProcesses,boxPercent,stepStat,levelStat,statusLevel,statusStep,statusBox};
}
function treasureChest(status){return `<span class="treasure-chest" aria-hidden="true"><i class="treasure-lid"></i><i class="treasure-body"></i><b></b><em>${status==='locked'?icon('lock',15):status==='done'?icon('check',16):icon('spark',16)}</em></span>`}
function treasureProgress(percent){return `<span class="treasure-progress" aria-label="نسبة التقدم ${percent}%"><i style="width:${percent}%"></i></span>`}
function studyMapHeader(model){const s=model.snap;return `<header class="treasure-map-hero"><div><span class="treasure-eyebrow">${icon('compass',18)} خريطة كنوز الدراسة</span><h1>كل كنز يفتح الطريق<br><em>إلى الكنز الذي بعده.</em></h1><p>ابدأ بالمستوى، ثم الخطوة، ثم الصندوق. الكنوز المكتملة تبقى مفتوحة للمراجعة، والكنوز القادمة تنتظر دورها.</p></div><div class="treasure-map-summary"><span>الصندوق الحالي</span><strong>${model.current===null?'اكتملت الرحلة':model.current}</strong><small>${model.current===null?'جمعت كل الكنوز':`المستوى ${model.currentPos.stage} · الخطوة ${model.currentPos.step} · الصندوق ${model.currentPos.box}`}</small></div></header>`}
function studyLevelsMap(model){
 return `<section class="treasure-map-panel"><div class="treasure-map-title"><div><span>ابدأ من هنا</span><h2>اختر المستوى</h2><p>تقدّم المستوى محسوب من تقدّم خطواته العشر.</p></div><strong>٥ مستويات</strong></div><div class="treasure-route treasure-level-route">${Array.from({length:5},(_,i)=>{const level=i+1,status=model.statusLevel(level),stat=model.levelStat(level),locked=status==='locked';return `<button class="treasure-node treasure-level ${status}" ${locked?'disabled':`data-study-level="${level}"`} aria-label="المستوى ${level}: ${esc(LiplipProgress.STAGES[i])}"><span class="treasure-node-index">0${level}</span>${treasureChest(status)}<span class="treasure-node-copy"><small>المستوى ${level}</small><strong>${esc(LiplipProgress.STAGES[i])}</strong><span>${status==='locked'?'لم تصل إليه بعد':status==='current'?'المستوى الحالي':stat.done+' / 10 خطوات مكتملة'}</span>${treasureProgress(stat.percent)}</span><b class="treasure-percent">${stat.percent}%</b></button>`}).join('')}</div></section>`
}
function studyStepsMap(model,level){
 const levelStat=model.levelStat(level);return `<section class="treasure-map-panel"><div class="treasure-map-breadcrumb"><button data-study-back="levels">${icon('back',17)} المستويات</button><span>المستوى ${level} · ${esc(LiplipProgress.STAGES[level-1])}</span></div><div class="treasure-map-title"><div><span>خريطة المستوى</span><h2>اختر الخطوة</h2><p>تقدّم كل خطوة محسوب من صناديقها العشرين.</p></div><strong>${levelStat.percent}%</strong></div><div class="treasure-route treasure-step-route">${Array.from({length:10},(_,i)=>{const step=i+1,status=model.statusStep(level,step),stat=model.stepStat(level,step),locked=status==='locked',name=LiplipProgress.STEP_NAMES[level-1][i];return `<button class="treasure-node treasure-step ${status}" ${locked?'disabled':`data-study-step="${step}"`}><span class="treasure-node-index">${String(step).padStart(2,'0')}</span>${treasureChest(status)}<span class="treasure-node-copy"><small>الخطوة ${step}</small><strong>${esc(name)}</strong><span>${status==='locked'?'مغلقة حتى تصل إليها':status==='current'?'الخطوة الحالية':stat.done+' / 20 صندوقاً مكتمل'}</span>${treasureProgress(stat.percent)}</span><b class="treasure-percent">${stat.percent}%</b></button>`}).join('')}</div></section>`
}
function studyBoxesMap(model,level,step){
 const stat=model.stepStat(level,step);return `<section class="treasure-map-panel"><div class="treasure-map-breadcrumb"><button data-study-back="steps">${icon('back',17)} الخطوات</button><button data-study-back="levels">المستوى ${level}</button><span>${esc(LiplipProgress.STEP_NAMES[level-1][step-1])}</span></div><div class="treasure-map-title"><div><span>كنوز الخطوة ${step}</span><h2>اختر الصندوق</h2><p>الصندوق يتقدّم عبر خمس عمليات تعلم، ثم يكتمل بعد اجتياز الامتحان النهائي.</p></div><strong>${stat.percent}%</strong></div><div class="treasure-process-key" aria-label="عمليات الصندوق الخمس">${STUDY_PROCESS_NAMES.map((name,i)=>`<span><b>${i+1}</b>${name}</span>`).join('')}<span class="exam-seal">${icon('check',14)} الامتحان يختم الصندوق</span></div><div class="treasure-box-grid">${Array.from({length:20},(_,i)=>{const box=i+1,id=(level-1)*200+(step-1)*20+box,status=model.statusBox(id),locked=status==='locked',done=status==='done',processes=done?5:model.boxProcesses(id),percent=model.boxPercent(id),next=done?'مكتمل · افتحه للمراجعة':status==='current'?(processes===5?'العمليات 5/5 · الامتحان النهائي متبقٍ':`التالي: ${STUDY_PHASE_LABELS[model.zone.phase]}`):'يفتح بعد إكمال الصندوق السابق';return `<button class="treasure-box ${status}" ${locked?'disabled':`data-study-box="${id}"`} aria-label="الصندوق ${box}: ${next}">${treasureChest(status)}<span class="treasure-box-number">${String(box).padStart(2,'0')}</span><strong>${esc(LiplipProgress.BOX_NAMES[i])}</strong><span class="treasure-process-dots" aria-label="${processes} من 5 عمليات مكتملة">${Array.from({length:5},(_,j)=>`<i class="${j<processes?'filled':''}"></i>`).join('')}</span><small>${next}</small>${treasureProgress(percent)}<b>${done?'مراجعة':status==='current'?'تابع':'مغلق'}</b></button>`}).join('')}</div></section>`
}
function studyPage(){const model=studyMapModel();if(!state.studyMapLevel||state.studyMapLevel<1||state.studyMapLevel>5)state.studyMapLevel=model.currentPos.stage;if(!state.studyMapStep||state.studyMapStep<1||state.studyMapStep>10)state.studyMapStep=model.currentPos.step;let body=studyLevelsMap(model);if(state.studyMapView==='steps')body=studyStepsMap(model,state.studyMapLevel);else if(state.studyMapView==='boxes')body=studyBoxesMap(model,state.studyMapLevel,state.studyMapStep);return `<main class="dashboard learning-page treasure-study">${studyMapHeader(model)}${body}<p class="treasure-map-note">${icon('lock',15)} الكنوز القادمة لا تُفتح قبل الوصول إليها. يمكنك دائماً الرجوع إلى أي مستوى أو خطوة أو صندوق أنهيته للمراجعة.</p></main>`}

function receptionPage(){const s=LiplipProgress.snapshot(state.progress);return `<main class="dashboard learning-page reception-layout reception-studio">${waypoint(s,'waypoint-reception')}<header class="studio-intro"><span class="studio-eyebrow">شاهد واقرأ <span aria-hidden="true">/</span> مساحة الاكتشاف</span><h1>تعلّم اللغة <em>خارج الكتاب.</em></h1><p>مَشهد تسمعه أو نصّ تعيشه. اختر ما يناسبك، ثم ارجع بكلمات جديدة إلى مسارك.</p><div class="studio-tags" aria-label="طُرق التعلّم"><span>${icon('sound',17)} استماع وفهم</span><span>${icon('file',17)} قراءة وفهم</span></div></header><div class="studio-choices"><article class="studio-choice studio-watch"><div class="studio-choice-top"><span class="choice-index">01 / WATCH</span><span class="choice-signal" aria-hidden="true"><i></i><i></i><i></i></span></div><div class="studio-watch-art" aria-hidden="true"><span class="studio-watch-caption">A little story<br>goes a long way.</span><span class="studio-play">${icon('play',32)}</span><span class="studio-filmbar"><i></i><i></i><i></i><i></i></span></div><div class="studio-choice-body"><span class="studio-choice-label">لمن يحب يسمع ويرى</span><h2>المشاهدة</h2><p>شاهد كيف تُقال الكلمات في موقف حقيقي، والتقط النبرة والسياق.</p><button data-experience="watching">افتح المشاهدة <span>${icon('arrow',19)}</span></button><small>تقييمات الاستماع: ${s.metrics.listening.count}</small></div></article><article class="studio-choice studio-read"><div class="studio-choice-top"><span class="choice-index">02 / READ</span><span class="choice-stars" aria-hidden="true">${icon('spark',23)}</span></div><div class="studio-read-art" aria-hidden="true"><div class="studio-page"><span>ONE MORE PAGE</span><strong>Words become<br>worlds.</strong><i></i><i></i><i></i><small>لُبلُب · دفتر القراءة</small></div><span class="studio-page-back"></span></div><div class="studio-choice-body"><span class="studio-choice-label">لمن يحب يكتشف بين السطور</span><h2>القراءة</h2><p>تتبّع فكرة، خمّن معنى، ولاحظ كيف تصبح الجملة جزءاً من حكاية.</p><button data-experience="reading">افتح القراءة <span>${icon('arrow',19)}</span></button><small>تقييمات القراءة: ${s.metrics.reading.count}</small></div></article></div><p class="studio-footnote">تظهر تقييمات المهارات بعد إكمال نشاط مُقيّم؛ هذه المساحات قيد الإعداد.</p></main>`}
function chatPage(){const s=LiplipProgress.snapshot(state.progress),first=state.chatMode===null;return `<main class="dashboard learning-page chat-layout talk-studio">${waypoint(s,'waypoint-chat')}<header class="talk-intro"><div class="talk-intro-copy"><span class="studio-eyebrow">مساحة المحادثة <span aria-hidden="true">/</span> خطوة بصوتك</span><h1>جرّب تقولها.<br><em>كل محاولة تقرّبك.</em></h1><p>استخدم كلمات صندوقك في حوار. اختر أسلوب التمرين أولاً، ثم اختر الكتابة أو الصوت.</p></div><div class="talk-illustration" aria-hidden="true"><span class="talk-bubble talk-bubble-one">Hello there!</span><span class="talk-bubble talk-bubble-two">هلا، شلونك؟</span><span class="talk-wave"><i></i><i></i><i></i><i></i><i></i></span></div></header><div class="talk-section-head"><div><span class="talk-step">${first?'01':'02'} / 02</span><h2>${first?'كيف تريد أن تتمرّن؟':'كيف تريد أن تتواصل؟'}</h2></div>${first?'<span class="talk-hint">ابدأ بالطريقة التي تريحك</span>':`<button class="mode-back" data-action="mode-reset">${icon('back',17)} تغيير المسار</button>`}</div><div class="talk-options">${first?`<article class="talk-option talk-guided"><span class="talk-option-icon">${icon('chat',28)}</span><span class="talk-option-kicker">مسار مُوجّه</span><h3>خلّينا نحكي معاً.</h3><p>تلميحات خطوة بخطوة تساعدك ترتّب أفكارك وتبني ردّك.</p><button data-mode="supervise">ابدأ التوجيه ${icon('arrow',20)}</button><span class="talk-option-number">01</span></article><article class="talk-option talk-free"><span class="talk-option-icon">${icon('bolt',28)}</span><span class="talk-option-kicker">مسار حر</span><h3>خذ راحتك بالكلام.</h3><p>جرّب ما تعلمته بطريقتك، واكتشف كيف تتصرف في الحوار.</p><button data-mode="practice">ابدأ التدريب ${icon('arrow',20)}</button><span class="talk-option-number">02</span></article>`:`<article class="talk-option talk-textual"><span class="talk-option-icon">${icon('keyboard',28)}</span><span class="talk-option-kicker">${state.chatMode==='supervise'?'التوجيه':'التدريب'} · كتابة</span><h3>اكتب الفكرة.</h3><p>رتّب كلماتك في رسائل قصيرة وخذ وقتك لاختيار التعبير.</p><button data-channel="text">ابدأ الكتابة ${icon('arrow',20)}</button><span class="talk-option-number">Aa</span></article><article class="talk-option talk-spoken"><span class="talk-option-icon">${icon('phone',28)}</span><span class="talk-option-kicker">${state.chatMode==='supervise'?'التوجيه':'التدريب'} · صوت</span><h3>خلّي صوتك يوصل.</h3><p>تدرّب على الإيقاع والنطق والطلاقة في مكالمة صوتية.</p><button data-channel="call">ابدأ المكالمة ${icon('arrow',20)}</button><span class="talk-option-number">02</span></article>`}</div><section class="talk-metrics"><div><span class="talk-step">مهاراتك في الحوار</span><h2>كل محادثة فرصة للتقدّم.</h2></div><div class="meter-row">${meter('التواصل','chat',s.metrics.communication.average,`${s.metrics.communication.count} تقييم`)}${meter('اللكنة','sound',s.metrics.accent.average,`${s.metrics.accent.count} تقييم`)}${meter('الطلاقة','bars',s.metrics.fluency.average,`${s.metrics.fluency.count} تقييم`)}</div></section></main>`}
function closetData(){
 const boxes=new Map(),getBox=id=>{if(!Number.isInteger(id)||id<1||id>1000)return null;if(!boxes.has(id))boxes.set(id,LiplipZone.getContent(id));return boxes.get(id)};
 const words=state.progress.vocabulary.map(entry=>{
  const matches=getBox(entry.boxId)?.vocab.filter(item=>['word','imageWord'].includes(item.type)&&item.en.toLocaleLowerCase()===entry.word.toLocaleLowerCase())||[];
  const original=matches.find(item=>item.image)||matches[0];
  return {word:entry.word,boxId:entry.boxId,ar:entry.ar||original?.ar||'',example:entry.example||original?.example||'',image:entry.image||original?.image||''}
 });
 const grammar=[...(state.progress.grammar||[])],saved=new Set(grammar.map(item=>`${item.boxId}:${item.type}:${item.id}`));
 for(const boxId of state.progress.completedBoxes)for(const item of getBox(boxId)?.grammar||[])if(['sentenceRule','questionRule','negativeRule'].includes(item.type)){const key=`${boxId}:${item.type}:${item.id}`;if(!saved.has(key)){grammar.push({boxId,id:item.id,type:item.type,title:item.title,formula:item.formula,en:item.en,ar:item.ar,body:item.body,example:item.example});saved.add(key)}}
 return {words,grammar}
}
function closetPosition(boxId){if(!boxId)return '';const p=LiplipProgress.location(boxId);return `المرحلة ${p.stage} · الخطوة ${p.step} · الصندوق ${p.box}`}
function closetItemsPage(data){const isWord=state.closetView==='words',items=isWord?data.words:data.grammar,count=items.length,index=Math.min(state.closetIndex,Math.max(0,count-1)),item=items[index];return `<main class="dashboard closet-page closet-detail"><div class="closet-detail-head"><button class="closet-back" data-action="closet-back">${icon('back',20)} العودة إلى الخزانة</button><span>خزانتي / ${isWord?'الكلمات':'القواعد'}</span></div><div class="closet-detail-title"><div><span class="section-kicker">${isWord?'دفتر المفردات':'دفتر القواعد'}</span><h1>${isWord?'كلمة وراء كلمة.':'قاعدة وراء قاعدة.'}</h1></div><span class="closet-page-counter">${count?index+1:0} / ${count}</span></div>${item?`<article class="closet-item ${isWord?'closet-word-item':'closet-rule-item'}"><div class="closet-item-top"><span>${isWord?'WORD / ENGLISH':item.type==='questionRule'?'QUESTION / RULE':item.type==='negativeRule'?'NEGATIVE / RULE':'SENTENCE / RULE'}</span><span>${closetPosition(item.boxId)}</span></div>${isWord?`${item.image?`<div class="closet-image"><img src="${esc(item.image)}" alt="${esc(item.word)}" loading="lazy" referrerpolicy="no-referrer"></div>`:''}<div class="closet-word-line"><strong dir="ltr" lang="en">${esc(item.word)}</strong><button data-closet-sound="${index}" aria-label="استمع إلى ${esc(item.word)}">${icon('sound',26)}</button></div><p class="closet-meaning">${esc(item.ar||'المعنى غير محفوظ لهذا العنصر')}</p>${item.example?`<div class="closet-example"><small>في جملة</small><p dir="ltr" lang="en">${esc(item.example)}</p></div>`:''}`:`<span class="closet-rule-kind">${item.type==='questionRule'?'صياغة سؤال':item.type==='negativeRule'?'صياغة النفي':'بناء جملة'}</span><h2>${esc(item.title||'قاعدة لغوية')}</h2><div class="closet-formula" dir="auto">${esc(item.formula)}</div>${item.ar?`<p class="closet-rule-explain" lang="ar" dir="rtl">${esc(item.ar)}</p>`:item.body?`<p class="closet-rule-explain">${esc(item.body)}</p>`:''}${item.en?`<p class="closet-rule-explain" lang="en" dir="ltr">${esc(item.en)}</p>`:''}${item.example?`<div class="closet-example"><small>مثال تطبيقي</small><p dir="ltr" lang="en">${esc(item.example)}</p></div>`:''}`}</article><div class="closet-pager"><button data-action="closet-prev" ${index===0?'disabled':''}>${icon('back',18)} السابق</button><span>${index+1} من ${count}</span><button data-action="closet-next" ${index===count-1?'disabled':''}>التالي ${icon('arrow',18)}</button></div>`:`<div class="closet-empty"><span>${icon(isWord?'book':'layers',42)}</span><h2>لا يوجد محتوى محفوظ بعد.</h2><p>تظهر هنا العناصر التي درستها بعد إكمال الصندوق.</p><button data-action="closet-back">العودة إلى الخزانة</button></div>`}</main>`}
function closetPage(){const data=closetData();if(state.closetView)return closetItemsPage(data);return `<main class="dashboard closet-page"><div class="closet-hero"><div><span class="section-kicker">خزانتي / حصيلة التعلّم</span><h1>كلمات وقواعد<br><em>تبقى معك.</em></h1><p>كل صندوق تُكمله يضيف ما تعلّمته إلى خزانة خاصة بك. افتح أي دفتر وراجع عنصراً واحداً في كل مرة.</p></div><div class="closet-hero-art" aria-hidden="true">${icon('layers',90)}<i></i><i></i></div></div><div class="closet-shelves"><article class="closet-shelf closet-shelf-words"><div class="closet-shelf-icon">${icon('book',34)}</div><span>دفتر الكلمات</span><strong>${data.words.length}</strong><p>كلمة درستها في الصناديق المكتملة، مع معناها ومثالها.</p><button data-action="closet-words" ${data.words.length?'':'disabled'}>افتح الكلمات ${icon('arrow',19)}</button></article><article class="closet-shelf closet-shelf-rules"><div class="closet-shelf-icon">${icon('layers',34)}</div><span>دفتر القواعد</span><strong>${data.grammar.length}</strong><p>قوانين الجملة والسؤال والنفي التي راجعتها في دروسك المكتملة.</p><button data-action="closet-grammar" ${data.grammar.length?'':'disabled'}>افتح القواعد ${icon('arrow',19)}</button></article></div>${!data.words.length&&!data.grammar.length?`<div class="closet-hint">خزانتك تنتظر إكمال صندوقك الأول. <button data-nav="الدراسة">اذهب إلى الدراسة ${icon('arrow',16)}</button></div>`:''}</main>`}
function resetLesson(){state.lessonTab='discover';state.lessonReviewed=[];state.lessonWritten=[];state.lessonSpoken=[];state.lessonAttempts={};state.lessonRating=null;state.lessonFeedback='';state.editorDraft=null}
function lessonReady(words){return words.length>=2&&words.every((_,i)=>state.lessonReviewed.includes(i)&&state.lessonWritten.includes(i)&&state.lessonSpoken.includes(i))&&state.lessonRating!==null}
function lessonPage(){const s=LiplipProgress.snapshot(state.progress);if(state.editorOpen)return lessonEditor(s);const lesson=LiplipContent.get(s.currentBox||s.totalBoxes,s.boxName);const words=lesson.words;const ready=lessonReady(words);const tabs=[['discover','استكشف',icon('book',18),state.lessonReviewed.length],['write','اكتب',icon('pen',18),state.lessonWritten.length],['speak','تكلّم',icon('sound',18),state.lessonSpoken.length]];return `<main class="lesson-shell"><div class="lesson-top"><button class="back" data-action="return-study">${icon('back',17)} العودة إلى الدراسة</button><button class="lesson-edit" data-action="toggle-editor">${icon('pen',17)} تعديل محتوى الدرس</button></div>${waypoint(s,'waypoint-study')}<div class="lesson-head"><div><span class="section-kicker">دفتر الصندوق ${s.position.box} · ${esc(s.stepName)}</span><h1>${esc(lesson.title)}</h1><p>${esc(lesson.goal)}</p></div><div class="lesson-round">${icon('book',57)}</div></div>${words.length===0?`<div class="lesson-empty"><span>${icon('pen',42)}</span><h2>هذا الصندوق ينتظر محتواه.</h2><p>أضف كلمتين على الأقل مع المعنى والمثال لتبدأ التعلّم. يمكنك تعديل أي صندوق من محرّر المحتوى.</p><button class="cta" data-action="toggle-editor">أضف محتوى الدرس ${icon('arrow',19)}</button></div>`:`<div class="lesson-workspace"><aside class="lesson-sidebar"><div class="lesson-progress"><span>تقدّمك في الدرس</span><strong>${state.lessonReviewed.length+state.lessonWritten.length+state.lessonSpoken.length} / ${words.length*3}</strong><div><i style="width:${Math.round((state.lessonReviewed.length+state.lessonWritten.length+state.lessonSpoken.length)/(words.length*3)*100)}%"></i></div></div><div class="lesson-tablist" role="tablist" aria-label="مراحل الدرس">${tabs.map(([key,label,mark,count],i)=>`<button role="tab" aria-selected="${state.lessonTab===key}" class="${state.lessonTab===key?'active':''}" data-lesson-tab="${key}"><span class="tab-number">0${i+1}</span>${mark}<span>${label}</span><small>${count}/${words.length}</small></button>`).join('')}</div><div class="lesson-tip">${icon('spark',20)} <p>تعلّم الكلمات أولاً، ثم اكتبها من الذاكرة، وبعدها استمع وردّدها.</p></div></aside><section class="lesson-stage">${state.lessonTab==='discover'?discoverLesson(words):state.lessonTab==='write'?writeLesson(words):speakLesson(words)}<p class="lesson-feedback" role="status">${esc(state.lessonFeedback)}</p><div class="lesson-complete"><div><strong>جاهز للخطوة التالية؟</strong><small>أكمل مراجعة الكلمات والكتابة والترديد قبل إنهاء الصندوق.</small></div><button class="cta" data-action="complete-lesson" ${ready?'':'disabled'}>أنهِ الصندوق ${icon('arrow',18)}</button></div></section></div>`}</main>`}
function discoverLesson(words){return `<div class="stage-heading"><span class="section-kicker">المرحلة الأولى · اكتشف</span><h2>تعرّف إلى الكلمات.</h2><p>اسمع الكلمة، اقرأ معناها، ثم علّمها كمراجَعة.</p></div><div class="flash-grid">${words.map((w,i)=>`<article class="flash-card ${state.lessonReviewed.includes(i)?'reviewed':''}"><div class="flash-top"><span>الكلمة 0${i+1}</span><button data-audio="${i}" aria-label="استمع إلى ${esc(w.term)}" title="استمع إلى الكلمة">${icon('sound',19)}</button></div><strong dir="ltr">${esc(w.term)}</strong><span class="translation">${esc(w.meaning)}</span><p dir="ltr">${esc(w.example)}</p><button class="review-button" data-review="${i}">${state.lessonReviewed.includes(i)?`${icon('check',17)} تمت المراجعة`:`${icon('check',17)} راجعت هذه الكلمة`}</button></article>`).join('')}</div>`}
function writeLesson(words){return `<div class="stage-heading"><span class="section-kicker">المرحلة الثانية · اكتب</span><h2>هل تتذكّرها؟</h2><p>اكتب الكلمة الإنجليزية المناسبة للمعنى. يمكنك المحاولة أكثر من مرة، وتُحتسب دقة أولى المحاولات.</p></div><form id="lesson-writing-form" class="writing-list">${words.map((w,i)=>`<div class="writing-row ${state.lessonWritten.includes(i)?'correct':''}"><div><span>0${i+1} · ${esc(w.meaning)}</span><small>${state.lessonWritten.includes(i)?`صحيح: ${esc(w.term)}`:state.lessonAttempts[i]?`تلميح: تبدأ بحرف ${esc(w.term[0].toUpperCase())}`:'اكتب المقابل الإنجليزي'}</small></div>${state.lessonWritten.includes(i)?icon('check',23):`<input name="answer${i}" dir="ltr" maxlength="80" autocomplete="off" aria-label="الترجمة الإنجليزية لـ ${esc(w.meaning)}" placeholder="Type in English">`}</div>`).join('')}<button class="lesson-check" type="submit">تحقّق من إجاباتي ${icon('arrow',18)}</button></form>`}
function speakLesson(words){return `<div class="stage-heading"><span class="section-kicker">المرحلة الثالثة · تكلّم</span><h2>اسمعها ثم قلها.</h2><p>استمع لكل كلمة وردّدها بصوتك. قيّم وضوح نطقك بنفسك؛ لا يستخدم هذا الدرس الميكروفون ولا يقيس لكنتك تلقائياً.</p></div><div class="speaking-list">${words.map((w,i)=>`<div class="speaking-row"><button data-audio="${i}" aria-label="شغّل نطق ${esc(w.term)}">${icon('sound',22)}</button><div><strong dir="ltr">${esc(w.term)}</strong><span>${esc(w.meaning)}</span></div><button class="spoken-check ${state.lessonSpoken.includes(i)?'checked':''}" data-spoken="${i}">${state.lessonSpoken.includes(i)?'ردّدتها':'ردّد الكلمة ثم اضغط'}</button></div>`).join('')}</div><fieldset class="rating-field"><legend>كيف كان نطقك؟ <small>تقييم ذاتي للتدرّب، وليس قياساً آلياً</small></legend><div>${[[40,'أحتاج تدريباً'],[70,'جيد'],[90,'واضح وواثق']].map(([value,label])=>`<label class="${state.lessonRating===value?'selected':''}"><input type="radio" name="pronunciation" value="${value}" data-rating="${value}" ${state.lessonRating===value?'checked':''}>${label}</label>`).join('')}</div></fieldset>`}
function editorDraftFromForm(){const form=document.getElementById('lesson-editor-form');if(!form)return state.editorDraft||LiplipContent.get(state.editorBox);const data=new FormData(form),count=Number(form.dataset.wordCount);return {title:String(data.get('title')||''),goal:String(data.get('goal')||''),words:Array.from({length:count},(_,i)=>({term:String(data.get(`term${i}`)||''),meaning:String(data.get(`meaning${i}`)||''),example:String(data.get(`example${i}`)||'')}))}}
function lessonEditor(s){const id=state.editorBox||s.currentBox||1;const draft=state.editorDraft||LiplipContent.get(id,LiplipProgress.BOX_NAMES[(id-1)%20]);const pos=LiplipProgress.location(id);return `<main class="lesson-shell editor-shell"><div class="lesson-top"><button class="back" data-action="toggle-editor">${icon('back',17)} العودة إلى الدرس</button><span class="editor-local">${icon('lock',15)} تعديلات محلية في هذا المتصفح</span></div><div class="editor-heading"><span class="section-kicker">استوديو المحتوى</span><h1>ابنِ درساً يستحق التذكّر.</h1><p>عدّل العنوان والهدف، وأضف الكلمات والمعاني والأمثلة أو احذفها. احفظ لتستخدم الدرس في صندوقك. التعديلات هنا لا تظهر لبقية المستخدمين.</p></div><div class="editor-layout"><aside class="editor-aside"><h3>اختر صندوقاً</h3><form id="editor-jump-form"><label for="editor-box">رقم الصندوق (١–١٠٠٠)</label><div><input id="editor-box" name="boxId" type="number" min="1" max="1000" value="${id}" required><button type="submit" aria-label="افتح الصندوق">${icon('arrow',19)}</button></div></form><div class="editor-location"><span>المرحلة ${pos.stage}</span><strong>${esc(LiplipProgress.STAGES[pos.stage-1])}</strong><span>الخطوة ${pos.step} · الصندوق ${pos.box}</span></div><p>دروس البداية الخمسة جاهزة للتعلّم. يمكنك إعداد أي صندوق آخر هنا. احفظ التغييرات قبل الانتقال إلى صندوق مختلف.</p></aside><form id="lesson-editor-form" class="editor-form" data-word-count="${draft.words.length}"><div class="editor-form-top"><div><span class="section-kicker">محتوى الصندوق ${id}</span><h2>تفاصيل الدرس</h2></div><span>${draft.words.length} / ١٢ كلمة</span></div><div class="field"><label for="lesson-title">عنوان الدرس</label><input id="lesson-title" name="title" maxlength="80" required value="${esc(draft.title)}"></div><div class="field"><label for="lesson-goal">هدف التعلّم</label><textarea id="lesson-goal" name="goal" maxlength="250" required rows="3">${esc(draft.goal)}</textarea></div><div class="editor-words-heading"><h3>بطاقات الكلمات</h3><button type="button" data-action="add-word" ${draft.words.length>=12?'disabled':''}>${icon('spark',16)} أضف كلمة</button></div>${draft.words.map((w,i)=>`<div class="editor-word"><div class="editor-word-title"><strong>بطاقة 0${i+1}</strong><button type="button" data-delete-word="${i}" aria-label="احذف البطاقة ${i+1}">${icon('close',17)} حذف</button></div><div class="editor-word-grid"><label>الكلمة الإنجليزية<input name="term${i}" dir="ltr" maxlength="80" value="${esc(w.term)}" placeholder="example"></label><label>المعنى بالعربية<input name="meaning${i}" maxlength="120" value="${esc(w.meaning)}" placeholder="المعنى"></label></div><label>مثال بالإنجليزية<input name="example${i}" dir="ltr" maxlength="220" value="${esc(w.example)}" placeholder="Use the word in a sentence."></label></div>`).join('')}<p class="notice ${state.editorMessage.startsWith('تم')?'success':'error'}" role="status">${esc(state.editorMessage)}</p><div class="editor-actions"><button class="cta" type="submit">احفظ الدرس ${icon('check',18)}</button><button type="button" class="editor-danger" data-action="delete-lesson">حذف محتوى الصندوق</button>${LiplipContent.hasStarter(id)?`<button type="button" class="editor-restore" data-action="restore-lesson">استعادة الدرس الأساسي</button>`:''}</div>${state.confirmDelete?`<div class="delete-confirm" role="alert"><strong>حذف محتوى الصندوق ${id}؟</strong><span>يمكنك كتابة درس جديد أو استعادة الدرس الأساسي إن وجد.</span><button type="button" data-action="confirm-delete">تأكيد الحذف</button><button type="button" data-action="cancel-delete">إلغاء</button></div>`:''}</form></div></main>`}
function lessonFinish(){const result=state.justCompleted||{};const s=LiplipProgress.snapshot(state.progress);return `<main class="lesson-shell finish-shell"><div class="finish-card"><span class="finish-symbol">${icon('check',68)}</span><span class="section-kicker">تم إنجاز الصندوق</span><h1>أحسنت، خلصت «${esc(result.title||'الدرس')}».</h1><p>راجعت الكلمات، كتبتها، وتدرّبت على نطقها. صارت الكلمات الجديدة في خزانتك، والصندوق التالي جاهز.</p><div class="finish-stats"><div><strong>${result.newWords||0}</strong><span>كلمة جديدة</span></div><div><strong>${result.writingScore||0}%</strong><span>دقة الكتابة</span></div><div><strong>${s.level}</strong><span>مستواك الحالي</span></div></div><div class="finish-actions"><button class="cta" data-action="next-lesson" ${s.currentBox===null?'disabled':''}>افتح الصندوق التالي ${icon('arrow',19)}</button><button class="editor-restore" data-action="return-study">العودة إلى الدراسة</button></div></div></main>`}
function normalizedAnswer(value){return String(value||'').trim().toLocaleLowerCase().replace(/[.,!?;:]+$/g,'').replace(/\s+/g,' ')}
function experienceComing(){const s=LiplipProgress.snapshot(state.progress);const c=state.comingContext||{};
 if(c.kind==='watching')return `<main class="experience-soon watch-experience"><div class="experience-frame"><button class="back" data-action="return-section">${icon('back',17)} العودة إلى شاهد واقرأ</button>${waypoint(s,'waypoint-dark')}<div class="cinema-scene"><div class="cinema-play">${icon('play',68)}</div><span>قريباً · مشاهدة</span></div><div class="experience-caption"><div><span class="section-kicker">فهم المسموع</span><h1>شاهد اللغة وهي تتحرّك.</h1><p>المقاطع وأنشطة الفهم المناسبة لصندوقك الحالي قيد الإعداد. المشاهدة وحدها لا تمنح تقييماً.</p></div><span>${icon('eye',50)}</span></div></div></main>`;
 if(c.kind==='reading')return `<main class="experience-soon read-experience"><div class="experience-frame"><button class="back" data-action="return-section">${icon('back',17)} العودة إلى شاهد واقرأ</button>${waypoint(s,'waypoint-paper')}<div class="reading-spread"><div class="reading-page"><span>liplip / ${esc(s.stepName)}</span><h1>${esc(s.boxName)}</h1><div class="reading-line"></div><div class="reading-line"></div><div class="reading-line short"></div></div><div class="reading-page"><span>قريباً · قراءة</span><h2>صفحة جديدة تنتظرك.</h2><p>نصوص وأسئلة فهم تناسب مستواك وخطوتك. القراءة تُحتسب فقط بعد إكمال نشاط مُقيّم.</p>${icon('file',46)}</div></div></div></main>`;
 if(c.kind==='study')return `<main class="experience-soon study-experience"><div class="experience-frame"><button class="back" data-action="return-section">${icon('back',17)} العودة إلى الدراسة</button>${waypoint(s,'waypoint-study')}<div class="study-preview"><span class="section-kicker">درس الصندوق ${s.position.box} · قريباً</span><h1>${esc(s.boxName)}</h1><div class="preview-lines"><i></i><i></i><i></i></div><p>نجهّز كلمات وتمارين نطق وكتابة لهذا الصندوق. لن يُحفظ تقدّم قبل إكمال الدرس فعلياً.</p></div></div></main>`;
 return `<main class="experience-soon chat-experience"><div class="experience-frame"><button class="back" data-action="return-section">${icon('back',17)} العودة إلى المحادثة</button>${waypoint(s,'waypoint-chat')}<div class="chat-preview"><span class="preview-bubble">${icon('chat',24)} مساحة جديدة للحوار</span><span class="preview-bubble other">${icon(c.icon||'phone',24)} قريباً</span><h1>${esc(c.kicker||'المحادثة')}</h1><p>عندما تتوفر الجلسات، ستظهر تقييمات التواصل واللكنة والطلاقة بعد تجربة فعلية.</p></div></div></main>`;
}
function settingsPage(){const s=LiplipProgress.snapshot(state.progress);return `<main class="dashboard settings-page"><div class="page-intro"><span class="section-kicker">الإعدادات</span><h1>مساحتك، باختيارك.</h1><p>ما زلنا نجهّز الإعدادات الكاملة. يمكنك الآن إدارة تقدم التعلّم المحفوظ محلياً على هذا الجهاز.</p></div><div class="settings-panel"><div class="tile-icon lilac">${icon('lock',27)}</div><h2>بيانات التعلّم المحلية</h2><p>التقدّم، الكلمات المكتسبة، ودرجات التمرين محفوظة في هذا المتصفح. المحتوى الذي كتبته في محرّر الدروس محفوظ محلياً بشكل منفصل، ولا يظهر للآخرين.</p><div class="settings-summary"><span>${s.vocabularyCount} كلمة</span><span>${s.completedCount} صندوق مكتمل</span></div><button class="editor-danger" data-action="reset-progress">امسح تقدّم التعلّم</button>${state.confirmReset?`<div class="delete-confirm" role="alert"><strong>هل تريد مسح تقدّم التعلّم على هذا الجهاز؟</strong><span>سيعود المستوى إلى A0 وتُمسح الكلمات والتقييمات. لن يُحذف المحتوى الذي ألفته.</span><button data-action="confirm-reset">نعم، امسح التقدّم</button><button data-action="cancel-reset">إلغاء</button></div>`:''}</div></main>`}
function coming(){if(state.page==='feature-soon'&&state.comingContext)return experienceComing();const s=sections.find(x=>x.name===state.nav)||sections[1];return `<main class="coming"><div class="coming-inner"><div class="coming-icon">${icon(s.icon,58)}</div><span class="section-kicker">${esc(s.name)}</span><h1>شيء حلو بالطريق.</h1><p>نعمل على تجهيز هذه المساحة بعناية. ترقّب طرقاً جديدة للتعلّم والتواصل قريباً.</p><button class="cta" data-nav="الرئيسية">ارجع للرئيسية ${icon('arrow',19)}</button></div></main>`}
function appView(){if(state.page==='lesson')return lessonPage();if(state.page==='lesson-finish')return lessonFinish();if(state.page==='feature-soon')return coming();if(state.nav==='الرئيسية')return dashboard();if(state.nav==='الدراسة')return studyPage();if(state.nav==='شاهد واقرأ')return receptionPage();if(state.nav==='تحدّث')return chatPage();if(state.nav==='خزانتي')return closetPage();if(state.nav==='الإعدادات')return settingsPage();return coming()}
function render(scroll=true){app.innerHTML=state.page==='zone'?LiplipZone.render({snapshot:LiplipProgress.snapshot(state.progress)}):header()+(state.page==='landing'?landing():state.page==='auth'?auth():state.page==='profile'?profile():state.page==='test'?test():`<div class="app-layout">${nav()}${appView()}</div>`);if(state.page==='zone')LiplipZone.afterRender();if(scroll)window.scrollTo(0,0)}
app.addEventListener('click',e=>{
 if(state.page==='zone'){const target=e.target.closest('[data-zone]');if(!target)return;e.preventDefault();const result=LiplipZone.click(target.dataset.zone,target,()=>render(false));if(result.exit){state.page='app';state.nav='الدراسة';render()}return}
 const provider=e.target.closest('[data-provider]');if(provider){document.getElementById('auth-message').textContent=`الدخول عبر ${provider.dataset.provider} غير مفعّل في النسخة التجريبية. يلزم ربط مزوّد الحسابات بخادم آمن.`;return}
 const navButton=e.target.closest('[data-nav]');if(navButton){state.nav=navButton.dataset.nav;state.page='app';state.comingContext=null;state.closetView=null;state.closetIndex=0;render();return}
 const experienceButton=e.target.closest('[data-experience]');if(experienceButton){const kind=experienceButton.dataset.experience;state.comingContext={kind,icon:kind==='watching'?'play':'file'};state.page='feature-soon';render();return}
 const modeButton=e.target.closest('[data-mode]');if(modeButton){state.chatMode=modeButton.dataset.mode;render();return}
 const channelButton=e.target.closest('[data-channel]');if(channelButton){const voice=channelButton.dataset.channel==='call';state.comingContext={kind:'chat',icon:voice?'phone':'keyboard',kicker:`${state.chatMode==='supervise'?'التوجيه':'التدريب'} · ${voice?'مكالمة صوتية':'محادثة كتابية'}`,text:'هذه التجربة قيد الإعداد. عندما تتوفر، ستُسجّل تقييمات التواصل واللكنة والطلاقة بعد جلسة فعلية.'};state.page='feature-soon';render();return}
 const lessonTab=e.target.closest('[data-lesson-tab]');if(lessonTab){state.lessonTab=lessonTab.dataset.lessonTab;state.lessonFeedback='';render(false);return}
 const audioButton=e.target.closest('[data-audio]');if(audioButton){const lesson=LiplipContent.get(LiplipProgress.snapshot(state.progress).currentBox);const word=lesson.words[Number(audioButton.dataset.audio)];if(word&&'speechSynthesis' in window&&typeof SpeechSynthesisUtterance!=='undefined'){try{window.speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(word.term);utterance.lang='en-US';utterance.rate=.86;window.speechSynthesis.speak(utterance)}catch{state.lessonFeedback='تعذّر تشغيل الصوت. اقرأ الكلمة وردّدها بنفسك.';render(false)}}else{state.lessonFeedback='الصوت غير متاح في هذا المتصفح. اقرأ الكلمة وردّدها بنفسك.';render(false)}return}
 const closetAudio=e.target.closest('[data-closet-sound]');if(closetAudio){const item=closetData().words[Number(closetAudio.dataset.closetSound)];if(item&&'speechSynthesis' in window&&typeof SpeechSynthesisUtterance!=='undefined'){try{window.speechSynthesis.cancel();const sound=new SpeechSynthesisUtterance(item.word);sound.lang='en-US';sound.rate=.86;window.speechSynthesis.speak(sound)}catch{}}return}
 const reviewed=e.target.closest('[data-review]');if(reviewed){const i=Number(reviewed.dataset.review);if(!state.lessonReviewed.includes(i))state.lessonReviewed.push(i);render(false);return}
 const spoken=e.target.closest('[data-spoken]');if(spoken){const i=Number(spoken.dataset.spoken);if(!state.lessonSpoken.includes(i))state.lessonSpoken.push(i);render(false);return}
 const rated=e.target.closest('[data-rating]');if(rated){state.lessonRating=Number(rated.dataset.rating);render(false);return}
 const deleteWord=e.target.closest('[data-delete-word]');if(deleteWord){state.editorDraft=editorDraftFromForm();state.editorDraft.words.splice(Number(deleteWord.dataset.deleteWord),1);state.editorMessage='';render(false);return}
 const button=e.target.closest('[data-action]');if(!button)return;e.preventDefault();const action=button.dataset.action;
 if(action==='landing')state.page='landing';
 else if(action==='auth'){state.page='auth';state.message=''}
 else if(action==='signup'||action==='signin'){state.mode=action;state.message=''}
 else if(action==='guest'){state.guest=true;state.profile=null;state.nav='الرئيسية';state.page='app';save()}
 else if(action==='closet-words'||action==='closet-grammar'){state.closetView=action==='closet-words'?'words':'grammar';state.closetIndex=0}
 else if(action==='closet-back'){state.closetView=null;state.closetIndex=0}
 else if(action==='closet-next'||action==='closet-prev'){const data=closetData(),total=state.closetView==='words'?data.words.length:data.grammar.length;state.closetIndex=Math.max(0,Math.min(total-1,state.closetIndex+(action==='closet-next'?1:-1)))}
 else if(action==='study-box'){const box=LiplipProgress.snapshot(state.progress).currentBox;if(box===null)return;LiplipZone.start(box);state.page='zone';state.nav='الدراسة'}
 else if(action==='open-editor'){const box=LiplipProgress.snapshot(state.progress).currentBox||1;LiplipZone.start(box);state.page='zone';state.nav='الدراسة';LiplipZone.click('control',{},()=>{})}
 else if(action==='return-study'){state.page='app';state.nav='الدراسة';state.editorOpen=false;state.editorDraft=null}
 else if(action==='toggle-editor'){state.editorOpen=!state.editorOpen;state.editorBox=LiplipProgress.snapshot(state.progress).currentBox||1;state.editorDraft=null;state.editorMessage='';state.confirmDelete=false}
 else if(action==='add-word'){state.editorDraft=editorDraftFromForm();if(state.editorDraft.words.length<12){state.editorDraft.words.push({term:'',meaning:'',example:''});state.editorMessage=''}else state.editorMessage='الحد الأقصى ١٢ كلمة في الصندوق.';render(false);return}
 else if(action==='delete-lesson'){state.confirmDelete=true;state.editorDraft=editorDraftFromForm()}
 else if(action==='cancel-delete'){state.confirmDelete=false}
 else if(action==='confirm-delete'){const persisted=LiplipContent.remove(state.editorBox);state.editorDraft=null;state.confirmDelete=false;state.editorMessage=persisted?'تم حذف المحتوى من هذا المتصفح.':'تم الحذف مؤقتاً، لكن المتصفح منع حفظ التغيير.';if(state.editorBox===LiplipProgress.snapshot(state.progress).currentBox)resetLesson()}
 else if(action==='restore-lesson'){const persisted=LiplipContent.restore(state.editorBox);state.editorDraft=null;state.confirmDelete=false;state.editorMessage=persisted?'تم استعادة الدرس الأساسي.':'تمت الاستعادة مؤقتاً، لكن المتصفح منع الحفظ.';if(state.editorBox===LiplipProgress.snapshot(state.progress).currentBox)resetLesson()}
 else if(action==='complete-lesson'){const snap=LiplipProgress.snapshot(state.progress);if(snap.currentBox===null)return;const lesson=LiplipContent.get(snap.currentBox,snap.boxName);if(!lessonReady(lesson.words))return;const before=snap.vocabularyCount;const score=Math.round(lesson.words.reduce((sum,_,i)=>sum+100/(state.lessonAttempts[i]||1),0)/lesson.words.length);try{state.progress=LiplipProgress.recordStudy(state.progress,{boxId:snap.currentBox,words:lesson.words.map(w=>w.term),pronunciation:state.lessonRating,writing:score});save();state.justCompleted={title:lesson.title,newWords:LiplipProgress.snapshot(state.progress).vocabularyCount-before,writingScore:score};state.page='lesson-finish';state.editorOpen=false}catch{state.lessonFeedback='تعذّر حفظ التقدّم. حاول مرة أخرى.'}}
 else if(action==='next-lesson'){const box=LiplipProgress.snapshot(state.progress).currentBox;if(box===null)return;LiplipZone.start(box);state.page='zone';state.nav='الدراسة'}
 else if(action==='mode-reset'){state.chatMode=null}
 else if(action==='reset-progress'){state.confirmReset=true}
 else if(action==='cancel-reset'){state.confirmReset=false}
 else if(action==='confirm-reset'){state.progress=LiplipProgress.hydrate(null);state.confirmReset=false;state.closetView=null;state.closetIndex=0;save()}
 else if(action==='return-section'){state.page='app';state.comingContext=null}
 else if(action==='logout'){state.profile=null;state.guest=false;state.chatMode=null;sessionStorage.removeItem('liplip-preview');state.page='landing';state.nav='الرئيسية'}
 render();
});
app.addEventListener('input',e=>{if(state.page==='zone'&&e.target.closest?.('#zone-quiz-form'))LiplipZone.remember(e.target);if(e.target.id==='birth'){const age=ageFromBirth(e.target.value);document.getElementById('age-display').textContent=age===null?'سنحسب عمرك تلقائياً.':`العمر: ${age} سنة`}});
app.addEventListener('change',e=>{if(state.page==='zone'&&e.target.id==='zone-import-file'&&e.target.files?.length)LiplipZone.importFile(e.target.files[0],()=>render(false))});
app.addEventListener('submit',e=>{
 e.preventDefault();if(!e.target.reportValidity())return;
 if(state.page==='zone'){const result=LiplipZone.submit(e.target.id,e.target,()=>render(false));if(result.complete){const snap=LiplipProgress.snapshot(state.progress);try{const before=snap.vocabularyCount;state.progress=LiplipProgress.recordStudy(state.progress,{boxId:snap.currentBox,...result.complete});save();LiplipZone.clear();state.justCompleted={title:snap.boxName,newWords:LiplipProgress.snapshot(state.progress).vocabularyCount-before,writingScore:result.complete.writing};state.page='lesson-finish';render()}catch{render(false)}}return}
 if(e.target.id==='editor-jump-form'){const id=Number(new FormData(e.target).get('boxId'));if(Number.isInteger(id)&&id>=1&&id<=1000){state.editorBox=id;state.editorDraft=null;state.editorMessage='';state.confirmDelete=false;render()}return}
 if(e.target.id==='lesson-editor-form'){const draft=editorDraftFromForm();try{const persisted=LiplipContent.save(state.editorBox,draft);state.editorDraft=null;state.confirmDelete=false;state.editorMessage=persisted?'تم حفظ الدرس في هذا المتصفح.':'تم التعديل مؤقتاً، لكن المتصفح منع تخزينه. قد تفقده عند إعادة التحميل.';if(state.editorBox===LiplipProgress.snapshot(state.progress).currentBox)resetLesson()}catch(error){state.editorDraft=draft;state.editorMessage=error.message}render(false);return}
 if(e.target.id==='lesson-writing-form'){const lesson=LiplipContent.get(LiplipProgress.snapshot(state.progress).currentBox);const answers=new FormData(e.target);let newCorrect=0;lesson.words.forEach((word,i)=>{if(state.lessonWritten.includes(i))return;const answer=String(answers.get(`answer${i}`)||'').trim();if(!answer)return;state.lessonAttempts[i]=(state.lessonAttempts[i]||0)+1;if(normalizedAnswer(answer)===normalizedAnswer(word.term)){state.lessonWritten.push(i);newCorrect++}});state.lessonFeedback=newCorrect?`إجابات صحيحة: ${newCorrect}. استمر حتى تكتب جميع الكلمات.`:'راجع التلميحات وجرّب مرة أخرى.';render(false);return}
 if(e.target.id==='auth-form'){state.guest=false;state.page=state.profile?'app':'profile';render();return}
 if(e.target.id==='profile-form'){const data=Object.fromEntries(new FormData(e.target));const age=ageFromBirth(data.birth);if(age===null||age<0||age>120){document.getElementById('profile-error').textContent='يرجى إدخال تاريخ ميلاد صحيح.';return}state.profile={...data,age};if(data.level==='unknown'){state.page='test'}else{save();state.page='app'}render();return}
 if(e.target.id==='test-form'){const data=new FormData(e.target);let score=0;questions.forEach((q,i)=>{const answer=Number(data.get(`q${i}`));state.testAnswers[i]=answer;if(answer===q.right)score++});state.profile.level=score<=1?'starter':score<=3?'elementary':'intermediate';state.page='app';save();render()}
});
render();
